CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS families (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (family_id uuid REFERENCES families ON DELETE CASCADE, account_id uuid REFERENCES accounts ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(family_id,account_id));
CREATE INDEX IF NOT EXISTS membership_account ON memberships(account_id);
CREATE TABLE IF NOT EXISTS invites (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('editor','viewer')), created_by uuid NOT NULL REFERENCES accounts, expires_at timestamptz NOT NULL, revoked_at timestamptz, accepted_by uuid REFERENCES accounts, accepted_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS people (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families ON DELETE CASCADE, name text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', description text NOT NULL DEFAULT '', linked_account_id uuid REFERENCES accounts ON DELETE SET NULL, created_at timestamptz DEFAULT now(), UNIQUE(family_id,id));
CREATE INDEX IF NOT EXISTS people_family ON people(family_id);
CREATE TABLE IF NOT EXISTS interviews (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families ON DELETE CASCADE, person_id uuid NOT NULL, created_by uuid NOT NULL REFERENCES accounts, title text NOT NULL, language text NOT NULL, consent_at timestamptz NOT NULL, consent_by uuid NOT NULL REFERENCES accounts, audio_consent boolean NOT NULL DEFAULT false, voice_consent boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','complete','withdrawn')), created_at timestamptz DEFAULT now(), UNIQUE(family_id,id), FOREIGN KEY(family_id,person_id) REFERENCES people(family_id,id));
CREATE TABLE IF NOT EXISTS passages (id uuid PRIMARY KEY, family_id uuid NOT NULL, interview_id uuid NOT NULL, speaker text NOT NULL CHECK(speaker IN ('interviewee','interviewer')), text text NOT NULL, language text NOT NULL, client_id text NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(interview_id,client_id), UNIQUE(family_id,id), FOREIGN KEY(family_id,interview_id) REFERENCES interviews(family_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS passages_interview ON passages(family_id,interview_id,created_at);
CREATE INDEX IF NOT EXISTS passages_search ON passages USING gin(to_tsvector('simple',text));
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY, family_id uuid NOT NULL, interview_id uuid NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','done','failed')), attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, error text, created_at timestamptz DEFAULT now(), FOREIGN KEY(family_id,interview_id) REFERENCES interviews(family_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(status,available_at);
CREATE TABLE IF NOT EXISTS claims (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families ON DELETE CASCADE, interview_id uuid NOT NULL, passage_id uuid NOT NULL, quote text NOT NULL, kind text NOT NULL CHECK(kind IN ('person','alias','parent','partner','event','fact')), subject_name text NOT NULL, object_name text, predicate text NOT NULL, value text NOT NULL, certainty text NOT NULL CHECK(certainty IN ('stated','uncertain')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','conflict')), subject_id uuid, object_id uuid, candidates jsonb NOT NULL DEFAULT '[]', reviewed_by uuid REFERENCES accounts, reviewed_at timestamptz, UNIQUE(family_id,id), FOREIGN KEY(family_id,interview_id) REFERENCES interviews(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,passage_id) REFERENCES passages(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,subject_id) REFERENCES people(family_id,id), FOREIGN KEY(family_id,object_id) REFERENCES people(family_id,id));
CREATE INDEX IF NOT EXISTS claims_review ON claims(family_id,status);
CREATE TABLE IF NOT EXISTS edges (id uuid PRIMARY KEY, family_id uuid NOT NULL, source_id uuid NOT NULL, target_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('parent','partner')), claim_id uuid NOT NULL, CHECK(source_id<>target_id), UNIQUE(claim_id), FOREIGN KEY(family_id,source_id) REFERENCES people(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,target_id) REFERENCES people(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,claim_id) REFERENCES claims(family_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS edges_out ON edges(family_id,source_id,kind);
CREATE INDEX IF NOT EXISTS edges_in ON edges(family_id,target_id,kind);
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY, family_id uuid NOT NULL, person_id uuid NOT NULL, title text NOT NULL, date_text text NOT NULL, claim_id uuid NOT NULL UNIQUE, FOREIGN KEY(family_id,person_id) REFERENCES people(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,claim_id) REFERENCES claims(family_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recordings (id uuid PRIMARY KEY, family_id uuid NOT NULL, interview_id uuid NOT NULL, object_key text NOT NULL UNIQUE, mime text NOT NULL, bytes int NOT NULL, created_at timestamptz DEFAULT now(), FOREIGN KEY(family_id,interview_id) REFERENCES interviews(family_id,id) ON DELETE CASCADE);
